def text_to_rows(apps, schema_editor):
    """The support acts typed so far become one other band each, as written ("Sangham and Novelist")."""
    OtherBand = apps.get_model("concerts", "OtherBand")
    for concert in apps.get_model("concerts", "Concert").objects.exclude(support_acts=""):
        OtherBand.objects.create(concert=concert, name=concert.support_acts)


def rows_to_text(apps, schema_editor):
    Concert = apps.get_model("concerts", "Concert")
    for concert in Concert.objects.filter(other_bands__isnull=False).distinct():
        names = [other.band.name if other.band else other.name for other in concert.other_bands.order_by("pk")]
        concert.support_acts = ", ".join(names)[:300]
        concert.save(update_fields=["support_acts"])


